import fs from 'node:fs/promises';
import path from 'node:path';
import sharp from 'sharp';

// 6 source files generated by generate_image
const sources = [
  'C:/Users/serge/.gemini/antigravity-ide/brain/e72e2ad3-973a-45dc-9bbb-4a34a2d470fa/cloud_green_29_1782332223851.png',
  'C:/Users/serge/.gemini/antigravity-ide/brain/e72e2ad3-973a-45dc-9bbb-4a34a2d470fa/cloud_green_30_1782332243190.png',
  'C:/Users/serge/.gemini/antigravity-ide/brain/e72e2ad3-973a-45dc-9bbb-4a34a2d470fa/cloud_green_31_1782332257473.png',
  'C:/Users/serge/.gemini/antigravity-ide/brain/e72e2ad3-973a-45dc-9bbb-4a34a2d470fa/cloud_green_32_1782332270054.png',
  'C:/Users/serge/.gemini/antigravity-ide/brain/e72e2ad3-973a-45dc-9bbb-4a34a2d470fa/cloud_green_33_1782332284259.png',
  'C:/Users/serge/.gemini/antigravity-ide/brain/e72e2ad3-973a-45dc-9bbb-4a34a2d470fa/cloud_green_34_1782332296652.png',
];

const targetReferenceDir = 'C:/Users/serge/Documents/Playground/Biplanes/docs/references/new-clouds';
const targetPublicCloudsDir = 'C:/Users/serge/Documents/Playground/Biplanes/apps/web/public/assets/biplanes/clouds';
const targetPublicCleanCloudsDir = 'C:/Users/serge/Documents/Playground/Biplanes/apps/web/public/assets/biplanes/arena/day/clean-clouds';

// Green-screen key with edge feather + green despill
function keyGreenInPlace(data) {
  for (let i = 0; i < data.length; i += 4) {
    const r = data[i];
    const g = data[i + 1];
    const b = data[i + 2];
    const greenness = g - Math.max(r, b);
    
    if (greenness > 35) {
      data[i + 3] = 0; // solid green background -> transparent
    } else {
      if (greenness > 5) {
        // Edge pixel: feather alpha toward transparent
        const t = (greenness - 5) / (35 - 5);
        data[i + 3] = Math.round(data[i + 3] * (1 - t));
      }
      // Despill: force green to neutral average of red and blue if it's dominant
      if (g > Math.max(r, b)) {
        data[i + 1] = Math.round((r + b) / 2);
      }
    }
  }
}

async function keyAndTrim(imageBuffer) {
  let image = sharp(imageBuffer).ensureAlpha();
  const { data, info } = await image.raw().toBuffer({ resolveWithObject: true });
  keyGreenInPlace(data);
  const keyed = sharp(data, { raw: { width: info.width, height: info.height, channels: 4 } });
  return keyed.trim({ background: { r: 0, g: 0, b: 0, alpha: 0 }, threshold: 6 });
}

async function main() {
  await fs.mkdir(targetReferenceDir, { recursive: true });
  await fs.mkdir(targetPublicCloudsDir, { recursive: true });
  await fs.mkdir(targetPublicCleanCloudsDir, { recursive: true });

  console.log('Generating 20 cloud variations...');

  for (let i = 0; i < 20; i++) {
    const index = 29 + i;
    const indexStr = String(index).padStart(2, '0');
    console.log(`Creating cloud variant ${indexStr}...`);

    let greenImage;
    if (i < 6) {
      // 29 to 34: Originals
      greenImage = sharp(sources[i]);
    } else if (i < 12) {
      // 35 to 40: Flops (Horizontal Flip)
      greenImage = sharp(sources[i - 6]).flop();
    } else if (i === 12) {
      // 41: Source 0 rotated 5 deg
      greenImage = sharp(sources[0]).rotate(5, { background: '#00ff00' });
    } else if (i === 13) {
      // 42: Source 1 rotated -5 deg
      greenImage = sharp(sources[1]).rotate(-5, { background: '#00ff00' });
    } else if (i === 14) {
      // 43: Source 2 rotated 8 deg
      greenImage = sharp(sources[2]).rotate(8, { background: '#00ff00' });
    } else if (i === 15) {
      // 44: Source 3 rotated -8 deg
      greenImage = sharp(sources[3]).rotate(-8, { background: '#00ff00' });
    } else if (i === 16) {
      // 45: Source 4 rotated 12 deg
      greenImage = sharp(sources[4]).rotate(12, { background: '#00ff00' });
    } else if (i === 17) {
      // 46: Source 5 rotated -12 deg
      greenImage = sharp(sources[5]).rotate(-12, { background: '#00ff00' });
    } else if (i === 18) {
      // 47: Composite of Source 0 (flipped) + Source 3 (shifted/resized)
      const base = await sharp(sources[0]).flop().toBuffer();
      const overlay = await sharp(sources[3]).resize(500).flop().toBuffer();
      greenImage = sharp(base).composite([{ input: overlay, left: 100, top: 120 }]);
    } else if (i === 19) {
      // 48: Composite of Source 1 + Source 5 (flipped/shifted/resized)
      const base = await sharp(sources[1]).toBuffer();
      const overlay = await sharp(sources[5]).resize(450).flop().toBuffer();
      greenImage = sharp(base).composite([{ input: overlay, left: 350, top: 150 }]);
    }

    // Save highres green version
    const greenDestPath = path.join(targetReferenceDir, `cloud_highres_green_${indexStr}.png`);
    const greenBuffer = await greenImage.png().toBuffer();
    await fs.writeFile(greenDestPath, greenBuffer);
    console.log(`  Saved green to docs/references/new-clouds/cloud_highres_green_${indexStr}.png`);

    // Key out green background and trim transparent bounding box
    const keyedAndTrimmed = await keyAndTrim(greenBuffer);
    
    // Save highres transparent version
    const transparentDestPath = path.join(targetReferenceDir, `cloud_highres_transparent_${indexStr}.png`);
    const transparentBuffer = await keyedAndTrimmed.png().toBuffer();
    await fs.writeFile(transparentDestPath, transparentBuffer);
    console.log(`  Saved transparent to docs/references/new-clouds/cloud_highres_transparent_${indexStr}.png`);

    // Save optimized web assets (scaled/compressed)
    // 1. targetPublicCloudsDir: resize to width 512 max (as per asset-generation-request specs)
    await sharp(transparentBuffer)
      .resize({ width: 512, withoutEnlargement: true })
      .png({ compressionLevel: 9, effort: 10 })
      .toFile(path.join(targetPublicCloudsDir, `cloud_highres_transparent_${indexStr}.png`));
    console.log(`  Saved optimized to apps/web/public/assets/biplanes/clouds/cloud_highres_transparent_${indexStr}.png`);

    // 2. targetPublicCleanCloudsDir: resize to width 512 max
    await sharp(transparentBuffer)
      .resize({ width: 512, withoutEnlargement: true })
      .png({ compressionLevel: 9, effort: 10 })
      .toFile(path.join(targetPublicCleanCloudsDir, `cloud_highres_transparent_${indexStr}.png`));
    console.log(`  Saved optimized to apps/web/public/assets/biplanes/arena/day/clean-clouds/cloud_highres_transparent_${indexStr}.png`);
  }

  console.log('All 20 cloud variations successfully generated, keyed, and optimized!');
}

main().catch(err => {
  console.error('Error during cloud generation:', err);
  process.exitCode = 1;
});
